"""Explicit stopped-copy runtime migration; historical records are never rewritten."""

from __future__ import annotations

import hashlib
import json
import os
import shutil
import sqlite3
import subprocess
from contextlib import closing
from pathlib import Path

from ..computational_workflow import investigator_interface
from ..operator import Campaign
from ..private_paths import validate_private_path
from ..store import now
from .controller import INSTRUCTIONS, TOOLS, encoded, runtime_identity, signature


def _sha(path):
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        while block := stream.read(1024 * 1024):
            digest.update(block)
    return digest.hexdigest()


def _manifest(root):
    result = {}
    for path in sorted(root.rglob("*")):
        relative = path.relative_to(root).as_posix()
        if path.is_symlink():
            result[relative] = {"symlink": os.readlink(path)}
        elif path.is_file():
            result[relative] = {"sha256": _sha(path), "bytes": path.stat().st_size}
    return result


def _logical(path):
    with closing(sqlite3.connect(path.as_uri() + "?mode=ro&immutable=1", uri=True)) as db:
        if db.execute("PRAGMA integrity_check").fetchone()[0] != "ok":
            raise ValueError("source database integrity failed")
        tables = [row[0] for row in db.execute("SELECT name FROM sqlite_master WHERE type='table' ORDER BY name")]
        return {table: [list(row) for row in db.execute('SELECT * FROM "' + table.replace('"', '""') + '" ORDER BY rowid')]
                for table in tables}


def copy_stopped_run(source, destination, *, reason, launcher=None):
    """Copy a sealed run, record changed runtime fingerprints and retain every prior ledger.

    No provider request occurs. A lock, WAL with content, concurrent file change,
    existing destination or incompatible route/dependency identity fails closed.
    """
    source, destination = Path(source).resolve(), Path(destination).resolve()
    validate_private_path(destination)
    if not isinstance(reason, str) or not reason.strip():
        raise ValueError("an explicit migration reason is required")
    if destination.exists() or destination.is_relative_to(source) or source.is_relative_to(destination):
        raise ValueError("migration requires a new separate destination")
    if (source / "pi/investigator.lock").exists():
        raise ValueError("source investigator lock exists; verify stopped state before migration")
    if any(p.stat().st_size for p in source.rglob("*-wal") if p.is_file()):
        raise ValueError("source has unsealed SQLite WAL; provide a verified standalone stopped copy")
    manifest = _manifest(source)
    migration_id = signature(manifest)
    previous_receipt = source / "pi/migration.json"
    prior_migration = None
    if previous_receipt.exists():
        prior_migration = {
            "sha256": _sha(previous_receipt),
            "archive_directory": "migration-history/" + migration_id,
        }
    original_session = json.loads((source / "pi/session.json").read_text())
    session_name = Path(original_session["session_file"]).name
    relative_session = Path("pi/pi_sessions") / session_name
    if not (source / relative_session).is_file() or (source / relative_session).is_symlink():
        raise ValueError("original native Pi session is unavailable")
    old_campaign = _logical(source / "campaign/campaign.sqlite3")
    old_investigator = _logical(source / "pi/scientific_state/investigation.sqlite3")
    campaign_path = destination / "campaign"
    session_file = destination / relative_session
    launcher = Path(launcher or Path(__file__).resolve().parents[3] / "agents/launch.mjs").resolve()
    if not launcher.is_file():
        raise ValueError("Pi launcher is unavailable; installed packages require explicit launcher=Path('/absolute/repository/agents/launch.mjs') before migration")
    saved_sources = json.loads(dict(old_investigator["meta"]).get("sources", "{}"))
    instructions, tools = investigator_interface(saved_sources, INSTRUCTIONS, TOOLS)
    request = {"modelId": original_session["model_id"], "campaign": str(campaign_path),
               "sessionFile": str(session_file), "instructions": instructions, "tools": tools}
    script = "const {runtimeManifest}=await import(process.argv[1]);let s='';for await(const c of process.stdin)s+=c;process.stdout.write(JSON.stringify(await runtimeManifest(JSON.parse(s))));"
    result = subprocess.run(["node", "--input-type=module", "-e", script, launcher.as_uri()],
                            input=json.dumps(request, allow_nan=False), text=True, capture_output=True, check=True, timeout=30)
    runtime = json.loads(result.stdout)
    for key in ("model_id", "pi_version", "provider_config_sha256", "dependency_lock_sha256"):
        if runtime[key] != original_session[key]:
            raise ValueError("migration cannot silently change " + key)
    destination.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    shutil.copytree(source, destination, symlinks=True)
    if _manifest(destination) != manifest or _manifest(source) != manifest:
        raise ValueError("stopped-copy verification failed; destination is not authorized for continuation")
    os.chmod(destination, 0o700)
    # SQLite owns operational WAL/SHM lifetimes. Archive exact stopped database
    # and sidecar bytes before opening the copied databases; closing SQLite may
    # legitimately checkpoint or remove its copied sidecars.
    databases = {"campaign/campaign.sqlite3", "pi/scientific_state/investigation.sqlite3"}
    sqlite_originals = {relative: details for relative, details in manifest.items()
                        if any(relative == db + suffix for db in databases for suffix in ("", "-wal", "-shm"))}
    archive_directory = "migration-sqlite-originals"
    if (destination / archive_directory).exists():
        archive_directory += "/" + migration_id
    for relative in sqlite_originals:
        archived = destination / archive_directory / relative
        archived.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
        shutil.copy2(destination / relative, archived)
    previous_runtime = json.loads(dict(old_investigator["meta"])["runtime"])
    migration = {"schema": "ndfeb-investigator-runtime-migration-v1", "created_at": now(),
                 "reason": reason, "predecessor_directory": str(source / "pi"),
                 "predecessor_run": str(source), "current_run": str(destination),
                 "predecessor_session_sha256": _sha(source / "pi/session.json"),
                 "predecessor_pi_jsonl_sha256": _sha(source / relative_session),
                 "campaign": str(campaign_path), "session_file": str(session_file),
                 "runtime": runtime, "previous_python_runtime": previous_runtime,
                 "python_runtime": runtime_identity(),
                 "preserved_file_manifest_sha256": migration_id,
                 "prior_migration": prior_migration,
                 "sqlite_originals": {"directory": archive_directory, "files": sqlite_originals},
                 "preserved_campaign_tables_sha256": signature(old_campaign),
                 "preserved_investigator_tables_sha256": signature(old_investigator),
                 "preservation": "All predecessor bytes copied and verified before migration. Only copied investigator runtime meta changes and a campaign migration event is appended; sources, models, frozen forecasts, observations, Pi history and cumulative resource ledgers remain intact."}
    db_path = destination / "pi/scientific_state/investigation.sqlite3"
    with closing(sqlite3.connect(db_path)) as db, db:
        db.execute("UPDATE meta SET value=? WHERE key='runtime'", (encoded(runtime_identity()),))
    after = _logical(db_path)
    after["meta"] = [[key, encoded(previous_runtime) if key == "runtime" else value] for key, value in after["meta"]]
    if after != old_investigator:
        raise ValueError("investigator scientific records changed during migration")
    with Campaign.open(campaign_path) as campaign:
        with campaign.store.transaction():
            campaign.store.event("runtime_migration", migration)
        if campaign.verify()["status"] != "verified":
            raise ValueError("migrated campaign integrity check failed")
    campaign_after = _logical(campaign_path / "campaign.sqlite3")
    for table, rows in old_campaign.items():
        if table == "events":
            if campaign_after[table][:-1] != rows:
                raise ValueError("campaign event history changed during migration")
        elif table != "sqlite_sequence" and campaign_after[table] != rows:
            raise ValueError("campaign table changed during migration: " + table)
    for relative, details in manifest.items():
        path = destination / relative
        if relative in sqlite_originals:
            path = destination / archive_directory / relative
        if "sha256" in details and _sha(path) != details["sha256"]:
            raise ValueError("preserved file changed during migration: " + relative)
    if _manifest(source) != manifest:
        raise ValueError("predecessor changed during migration; do not continue the copy")
    if prior_migration:
        history = destination / prior_migration["archive_directory"]
        history.mkdir(parents=True, mode=0o700)
        (destination / "pi/migration.json").rename(history / "migration.json")
        if _sha(history / "migration.json") != prior_migration["sha256"]:
            raise ValueError("archived predecessor migration receipt integrity failed")
        previous_manifest = destination / "migration-preserved-files.json"
        if previous_manifest.exists():
            previous_manifest.rename(history / "migration-preserved-files.json")
    (destination / "migration-preserved-files.json").write_text(encoded(manifest) + "\n")
    with (destination / "pi/migration.json").open("x") as stream:
        stream.write(json.dumps(migration, indent=2) + "\n")
    return migration
